do
    local genv = (type(getgenv) == "function") and getgenv() or nil
    if genv and type(getfenv) == "function" then
        local env = getfenv(1) 
        if not rawequal(env, genv) then
            local old = getmetatable(env)
            local oldIndex = old and old.__index
            pcall(setmetatable, env, {
                __index = function(t, k)
                    local v = genv[k] 
                    if v ~= nil then
                        return v
                    end
                    if type(oldIndex) == "function" then
                        return oldIndex(t, k)
                    elseif type(oldIndex) == "table" then
                        return oldIndex[k]
                    end
                    return nil
                end,
                __newindex = function(_, k, v)
                    genv[k] = v
                end,
            })
        end
    end
end

