    loader = {
        modules = {},
        owners = {},
        bundleUrls = {},
        loaded = {},
        exports = {},
        G = {},
        S = {},
        CFG = {},
    }
    sandboxEnv._CIPHER_ENV_c0ed928f2091e7ab997e4bb1 = loader
end

local require_api = {}

-- original host require, captured before we shadow the concept
local hostRequire = (type(require) == "function") and require or nil

-- bundle name -> remote url (dormant in a local build; the bundles are inlined,
-- so require() below only reaches these if an unregistered module is resolved)
local BASE = "https://cipher.pink/api/loader/bundle/210b5cd022438430f9833169/"
local GEN = "?generation=f457979ff19cc4f66bddc388482b8560"
for _, name in ipairs({
    "core", "server", "combat", "player", "world", "automation",
    "defense", "diagnostics", "movement", "visuals", "utility", "ui",
}) do
    if loader.bundleUrls[name] == nil then
        loader.bundleUrls[name] = BASE .. name .. ".lua" .. GEN
    end
end

