    if loader.owners[id] == nil then
        loader.owners[id] = bundle
    end
end

function loader.key(name)
    local h1 = 202299689
    local h2 = 253792744
    for i = 1, #name do
        local b = string.byte(name, i)
        h1 = (h1 * 257 + b) % 2147483647
        h2 = (h2 * 263 + b) % 2147483629
    end
    return "m" .. string.format("%.0f", h1) .. "_" .. string.format("%.0f", h2)
end

function loader.register(id, bundle, fn, leaf)
    loader.modules[id] = { bundle = bundle, fn = fn, leaf = leaf, value = nil, ran = false }
    loader.owners[id] = bundle
end

local MX

function loader.resolve(idOrLeaf, isId)
    local id = idOrLeaf
    if not isId then
        id = loader.key(idOrLeaf)
    end
    local ir = loader.modules[id]
    if not ir then
        local owner = loader.owners[id]
        if owner and not loader.loaded[owner] then
            require_api.require(owner)
        end
        ir = loader.modules[id]
    end
    if not ir then
        error("Cipher: module '" .. tostring(id) .. "' is not in any bundle", 2)
    end
    if ir.loading then
        error("Cipher: circular module dependency", 2)
    end
    if not ir.ran then
        ir.loading = true
        local ok, result = pcall(ir.fn, MX, require_api)
        ir.loading = false
        if not ok then
            error(result, 0)
        end
        ir.value = result
        ir.ran = true
    end
    return ir.value
end

function loader.mount(bundleName)
    local proxy = {}
    setmetatable(proxy, {
        __index = function(_, leafName)
            local hashed = loader.key(leafName)
            for id, mod in pairs(loader.modules) do
                if mod.bundle == bundleName and (mod.leaf == hashed or id == hashed) then
                    return loader.resolve(id, true)
                end
            end
            return nil
        end,
    })
    return proxy
end

MX = function(nameOrInstance, ...)
    if type(nameOrInstance) == "string" then
        local hashed = loader.key(nameOrInstance)
        if loader.modules[hashed] or loader.owners[hashed] then
            return loader.resolve(hashed, true)
        end
    end
    if type(hostRequire) == "function" then
        return hostRequire(nameOrInstance, ...)
    end
    error("Cipher: cannot require " .. tostring(nameOrInstance), 2)
end

-- pcall-protected _G[name] getter, used to probe for executor http globals
local function safeGlobal(name)
    local value
    pcall(function()
        value = sandboxEnv[name]
    end)
    if value == nil then
        pcall(function()
            value = _G and _G[name]
        end)
    end
    return value
end

-- remote fetch used by require_api.require; dormant in a local build
local function httpFetch(url)
    local syn = safeGlobal("syn")
    local http = safeGlobal("http")
    local request = (type(syn) == "table" and syn.request)
        or (type(http) == "table" and http.request)
        or safeGlobal("http_request")
        or safeGlobal("request")

    local cipherKey
    pcall(function()
        cipherKey = sandboxEnv.CipherKey or (_G and _G.CipherKey)
    end)

    local headers = { Accept = "*/*" }
    if cipherKey ~= nil and tostring(cipherKey) ~= "" then
        headers["x-cipher-loader-key"] = tostring(cipherKey)
    end

    if type(request) == "function" then
        local ok, res = pcall(request, { Url = url, Method = "GET", Headers = headers })
        if ok and type(res) == "table" then
            return res.Body or res.body
        elseif ok and type(res) == "string" then
            return res
        end
    end

    local target = url
    if cipherKey ~= nil and tostring(cipherKey) ~= "" then
        local sep = string.find(url, "?", 1, true) and "&" or "?"
        target = url .. sep .. "key=" .. tostring(cipherKey)
    end

    local ok, body = pcall(function()
        return game:HttpGet(target, true)
    end)
    if ok and type(body) == "string" then
        return body
    end
    return nil
end

function require_api.require(id)
    if loader.loaded[id] then
        return loader.exports[id]
    end
    local url = loader.bundleUrls[id]
    if not url then
        error("Cipher: unknown bundle '" .. tostring(id) .. "'", 2)
    end
    local source = httpFetch(url)
    if type(source) ~= "string" or source == "" then
        error("Cipher: bundle '" .. tostring(id) .. "' could not be authorized", 2)
    end
    local chunk, compileErr = loadstring(source)
    if not chunk then
        error("Cipher: bundle '" .. tostring(id) .. "' failed to compile: " .. tostring(compileErr), 2)
    end
    local value = chunk()
    loader.loaded[id] = true
    loader.exports[id] = value
    return value
end

function require_api.lazy(id)
    return function()
        return require_api.require(id)
    end
end

function require_api.unload(id)
    loader.loaded[id] = nil
    loader.exports[id] = nil
    for modId, mod in pairs(loader.modules) do
        if mod.bundle == id then
            loader.modules[modId] = nil
        end
    end
    if collectgarbage then
        pcall(collectgarbage, "collect")
    end
end

function require_api.loaded(id)
    return loader.loaded[id] == true
end

function require_api.module(leaf)
    return loader.resolve(leaf)
end

-- Cipher.G / Cipher.S / Cipher.CFG read through to the shared loader tables
setmetatable(require_api, {
    __index = function(_, k)
        if k == "G" then
            return loader.G
        elseif k == "S" then
            return loader.S
        elseif k == "CFG" then
            return loader.CFG
        end
        return nil
    end,
})

getgenv().Cipher = require_api

